import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"中吕·山坡羊春日二首","description":"","frontmatter":{"title":"中吕·山坡羊春日二首","date":"2026-11-11T00:00:00.000Z","seq":9,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/中吕·山坡羊春日二首.md","filePath":"blogs/元曲·张可久/中吕·山坡羊春日二首.md"}'),o={name:"blogs/元曲·张可久/中吕·山坡羊春日二首.md"};function c(l,a,n,_,m,r){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="中吕·山坡羊春日二首" tabindex="-1">中吕·山坡羊春日二首 <a class="header-anchor" href="#中吕·山坡羊春日二首" aria-label="Permalink to &quot;中吕·山坡羊春日二首&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">芙蓉春帐，葡萄新酿，一声《金缕》樽前唱。</p><p class="poem-stanza">锦生香，翠成行，醒来犹问春无恙，花边醉来能几场？妆，黄四娘。</p><p class="poem-stanza">狂，白侍郎。</p><p class="poem-stanza">西湖沉醉，东风得意，玉骢骤响黄金辔。</p><p class="poem-stanza">赏春归，看花回，宝香已暖鸳鸯被，萝绕绿窗初睡起。</p><p class="poem-stanza">痴，人未知。</p><p class="poem-stanza">噫，春去矣。</p><p class="poem-stanza">雪夜扁舟乘兴，读书相映，不如高卧柴门静。</p><p class="poem-stanza">唾壶冰，短檠灯，隔窗孤月悬秋镜，长笛不知何处声？惊，人睡醒。</p><p class="poem-stanza">清，梅弄影。</p><p class="poem-stanza">别怀梨花都谢，春衫初卸，绿阴空锁闲台榭。</p><p class="poem-stanza">远山叠，暮云遮，青青杨柳连官舍。</p><p class="poem-stanza">此景此情难弃舍，车，且慢些。</p><p class="poem-stanza">别，人去也。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
